from cmath import exp, phase
from itertools import combinations
from typing import Sequence


def complex_kth_root(w: complex, k: int) -> complex:
    """A principal k-th root of a complex number."""
    if w == 0:
        return 0
    return abs(w) ** (1.0 / k) * exp(1j * phase(w) / k)


def constants_are_dio(constants: Sequence[complex], k: int, n: complex,
                      tol: float = 1e-9) -> bool:
    """Check that every pairwise shifted product is a perfect k-th power over C."""
    for a, b in combinations(constants, 2):
        val = a * b + n
        c = complex_kth_root(val, k)
        if abs(c ** k - val) > tol:
            return False
    return True


def demo(sizes: Sequence[int] = (3, 10, 50, 200), k: int = 2,
         n: complex = 1) -> None:
    for N in sizes:
        constants = [complex(i + 1) for i in range(N)]
        print(f"|A| = {N:4d}:  D_{k}({n}) holds over C? "
              f"{constants_are_dio(constants, k, n)}")
    print("=> No absolute size bound exists among constants.")


if __name__ == "__main__":
    demo()

from fractions import Fraction
from typing import List, Optional, Sequence

Poly = List[Fraction]


def poly(coeffs: Sequence[object]) -> Poly:
    p = [Fraction(c) for c in coeffs]
    while len(p) > 1 and p[-1] == 0:
        p.pop()
    return p


def degree(p: Poly) -> int:
    return -1 if all(c == 0 for c in p) else len(p) - 1


def mul(p: Poly, q: Poly) -> Poly:
    out = [Fraction(0)] * (len(p) + len(q) - 1)
    for i, a in enumerate(p):
        for j, b in enumerate(q):
            out[i + j] += a * b
    return poly(out)


def add(p: Poly, q: Poly) -> Poly:
    n = max(len(p), len(q))
    out = [Fraction(0)] * n
    for i, c in enumerate(p):
        out[i] += c
    for i, c in enumerate(q):
        out[i] += c
    return poly(out)


def power(p: Poly, k: int) -> Poly:
    r: Poly = [Fraction(1)]
    for _ in range(k):
        r = mul(r, p)
    return r


def is_kth_power(p: Poly, k: int) -> bool:
    """Brute-force test whether p is a rational-polynomial k-th power."""
    d = degree(p)
    if d < 0:
        return True
    if d % k != 0:
        return False
    # Search small-coefficient candidates c of degree d/k.
    m = d // k
    from itertools import product
    grid = [Fraction(v) for v in range(-6, 7)]
    for coeffs in product(grid, repeat=m + 1):
        if coeffs[-1] == 0:
            continue
        if power(list(coeffs), k) == p:
            return True
    return False


def demo() -> None:
    a, b, n = poly([1, 1]), poly([-1, 1]), poly([5])
    prod = add(mul(a, b), n)
    print(f"deg(a*b + n) = {degree(prod)} = 2d with d = 1")
    print(f"perfect cube (k=3)?  {is_kth_power(prod, 3)}  (law needs 3 | 2)")
    print(f"perfect square (k=2)? {is_kth_power(prod, 2)}  (law needs 2 | 2)")


if __name__ == "__main__":
    demo()

from fractions import Fraction
from itertools import combinations
from typing import List, Optional, Sequence

Poly = List[Fraction]


def poly(coeffs: Sequence[object]) -> Poly:
    p = [Fraction(c) for c in coeffs]
    while len(p) > 1 and p[-1] == 0:
        p.pop()
    return p


def mul(p: Poly, q: Poly) -> Poly:
    out = [Fraction(0)] * (len(p) + len(q) - 1)
    for i, a in enumerate(p):
        for j, b in enumerate(q):
            out[i + j] += a * b
    return poly(out)


def add(p: Poly, q: Poly) -> Poly:
    n = max(len(p), len(q))
    out = [Fraction(0)] * n
    for i, c in enumerate(p):
        out[i] += c
    for i, c in enumerate(q):
        out[i] += c
    return poly(out)


def power(p: Poly, k: int) -> Poly:
    r: Poly = [Fraction(1)]
    for _ in range(k):
        r = mul(r, p)
    return r


def is_square(p: Poly) -> bool:
    from itertools import product
    d = -1 if all(c == 0 for c in p) else len(p) - 1
    if d < 0:
        return True
    if d % 2 != 0:
        return False
    m = d // 2
    grid = [Fraction(v) for v in range(-6, 7)]
    return any(coeffs[-1] != 0 and power(list(coeffs), 2) == p
               for coeffs in product(grid, repeat=m + 1))


def is_dio_set(members: Sequence[Poly], n: Poly) -> bool:
    return all(is_square(add(mul(a, b), n)) for a, b in combinations(members, 2))


def demo() -> None:
    a = poly([2, 3])                 # 3x + 2
    n_sq = power(poly([1, 1]), 2)     # (x+1)^2, a perfect square
    n_x = poly([0, 1])               # x, not a perfect square
    print(f"n = (x+1)^2 square? {is_square(n_sq)};  "
          f"{{0, 3x+2}} is D_2(n)? {is_dio_set([poly([0]), a], n_sq)}")
    print(f"n = x square? {is_square(n_x)};  "
          f"{{0, 3x+2}} is D_2(n)? {is_dio_set([poly([0]), a], n_x)}")


if __name__ == "__main__":
    demo()

